insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_interviewee','interviewee','noun','a person who is asked questions in a formal meeting, for example when applying for a job','[{"senseId":"interviewee_1","meaning":"a person who is asked questions in a formal meeting, for example when applying for a job","acceptedParaphrases":["person who answers the questions","person being asked questions by a panel"],"masteryContexts":[{"contextId":"u7_11_interviewee_meaning","text":"A nervous interviewee can improve the whole meeting simply by sitting up straight and making eye contact.","meaning":"the person who answers the questions","wrongMeanings":["the person who asks the questions","the person who writes the final report","the person who prepares the room"]},{"contextId":"u7_11_interviewee_paraphrase","text":"The interviewer thanked the interviewee for coming and said that a decision would be made by Friday.","meaning":"a person being questioned at a job meeting","wrongMeanings":["a person being trained in a new job","a person being paid for a day of work","a person being introduced to a new team"]}],"situationDistractors":["A young man sat opposite three people and answered each of their questions in turn.","A woman told a reporter about her life while the microphone recorded every word.","A student explained to a university panel why she wanted to study medicine.","The chef carried a tray of cups from the kitchen to the dining room.","A taxi driver waited outside the hotel with the engine running.","The class listened quietly while the teacher read the notice aloud."],"gapDistractors":[{"contextId":"u7_11_interviewee_gap_1","answer":"interviewee","wrong":["passenger","harbour","recipe"]},{"contextId":"u7_11_interviewee_gap_2","answer":"interviewee","wrong":["museum","ticket","umbrella"]},{"contextId":"u7_11_interviewee_gap_3","answer":"interviewee","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["intervieuee","interviewe","interviwee","interveiwee","interviewie","intervewee"],"masteryPassages":[{"passageId":"u7_11_interviewee_passage_1","contextId":"u7_11_interviewee_gap_1","text":"The panel asked five questions in twenty minutes, and the young ____ answered each one calmly. She paused before she spoke and gave a short example every time.","answer":"interviewee"},{"passageId":"u7_11_interviewee_passage_2","contextId":"u7_11_interviewee_gap_2","text":"Many people believe that the interviewer must do all the talking, but that is not true. A strong ____ explains ideas clearly and also asks one or two sensible questions at the end.","answer":"interviewee"}],"contextDependentParaphrases":[],"wrongParaphrases":["person who asks the questions","person who writes the advert","person who checks the answers"],"misleadingDistractors":["a person who asks the questions at a meeting","a person who writes the job advertisement","a person who checks the answers afterwards"],"teacherNote":"Noun: the person who is asked questions in a formal meeting, such as a job or college interview. Boundary: the interviewee answers and the interviewer asks (a separate target in this unit). The ending -ee marks the person who receives the action."}]'::jsonb,'[]'::jsonb,'["a nervous interviewee","the interviewee answered","help the interviewee relax"]'::jsonb,'live'),
('vocab_referee','referee','noun','a person who gives an employer or college an opinion of your character and ability','[{"senseId":"referee_1","meaning":"a person who gives an employer or college an opinion of your character and ability","acceptedParaphrases":["person who speaks well of you to an employer","someone who gives an opinion of your character"],"masteryContexts":[{"contextId":"u7_12_referee_meaning","text":"Her former headteacher agreed to be her referee for the university application.","meaning":"a person who gives an opinion of someone’s character","wrongMeanings":["a person who controls the rules of a game","a person who chooses students for a course","a person who marks the final exam papers"]},{"contextId":"u7_12_referee_paraphrase","text":"The employer telephoned his referee and asked how he had behaved when he worked in the café.","meaning":"a person named to speak about your work","wrongMeanings":["a person named to replace you at work","a person named to pay your wages","a person named to train new workers"]}],"situationDistractors":["A teacher wrote a short letter saying that a student was hard-working and reliable.","A manager agreed to answer an employer’s questions about a former worker.","A young woman put the name of her old supervisor on her job form.","The driver parked the minibus and opened the doors for the students.","A cat slept on the warm windowsill while the rain fell outside.","The team captain carried the cup onto the stage."],"gapDistractors":[{"contextId":"u7_12_referee_gap_1","answer":"referee","wrong":["neighbour","passenger","recipe"]},{"contextId":"u7_12_referee_gap_2","answer":"referee","wrong":["harbour","ticket","umbrella"]},{"contextId":"u7_12_referee_gap_3","answer":"referee","wrong":["museum","carpet","staircase"]}],"spellingErrors":["referree","refferee","refree","referie","reffree","refaree"],"masteryPassages":[{"passageId":"u7_12_referee_passage_1","contextId":"u7_12_referee_gap_1","text":"The application form asked for the names of two people who knew Hamza well. He chose his old teacher as one ____ and his football coach as the other, because both had seen him work hard.","answer":"referee"},{"passageId":"u7_12_referee_passage_2","contextId":"u7_12_referee_gap_2","text":"Before she was offered the job, the manager telephoned Leila’s ____ to ask whether she was reliable and honest. The answer was very positive, and the offer came the next day.","answer":"referee"}],"contextDependentParaphrases":[],"wrongParaphrases":["person who controls a game","person who chooses staff","person who checks exam answers"],"misleadingDistractors":["a person who controls a sports match and applies the rules","a person who chooses the people who will be offered a job","a person who checks the answers in an exam"],"teacherNote":"Taught in its job sense only: a person named on a job or college application who can say what you are like and how well you work. The sports sense (a person who controls a match) is a different meaning and is not taught here. Related target in this unit: reference (the letter or statement the referee writes). Spelling: referee, with three e’s and two r’s."}]'::jsonb,'[]'::jsonb,'["ask someone to be your referee","a referee for a job","contact a referee"]'::jsonb,'live'),
('vocab_reference','reference','noun','a short written statement from someone who knows you, saying whether you are suitable for a job or a course','[{"senseId":"reference_1","meaning":"a short written statement from someone who knows you, saying whether you are suitable for a job or a course","acceptedParaphrases":["written opinion from someone who knows you","letter that recommends you for a job"],"masteryContexts":[{"contextId":"u7_13_reference_meaning","text":"The manager promised to write a reference that mentioned Sana’s honesty and hard work.","meaning":"a written statement about someone’s suitability","wrongMeanings":["a list of the books someone has read","a short note about the time of a meeting","a number that identifies a customer"]},{"contextId":"u7_13_reference_paraphrase","text":"Without a reference from a previous employer, the company could not check how reliable the applicant had been.","meaning":"a statement that says if someone is suitable","wrongMeanings":["a record that shows how much someone was paid","a form that states where someone lives","a photograph that proves who someone is"]}],"situationDistractors":["A teacher wrote a letter saying that a student was polite, honest and keen to learn.","A former boss described a worker’s strengths in a short signed statement.","A coach wrote a page about a player’s character for her university application.","The conductor raised his arms and the orchestra began to play.","A girl painted a picture of the harbour for her art lesson.","The farmer drove the tractor across the muddy field."],"gapDistractors":[{"contextId":"u7_13_reference_gap_1","answer":"reference","wrong":["holiday","recipe","invitation"]},{"contextId":"u7_13_reference_gap_2","answer":"reference","wrong":["souvenir","umbrella","sandwich"]},{"contextId":"u7_13_reference_gap_3","answer":"reference","wrong":["carpet","staircase","bicycle"]}],"spellingErrors":["referance","refrence","referense","referece","refernce","referrence"],"masteryPassages":[{"passageId":"u7_13_reference_passage_1","contextId":"u7_13_reference_gap_1","text":"Nobody at the company knew Kamal personally, so the manager asked him to provide a ____ from his last job. His old supervisor wrote that he was always on time and very good with customers.","answer":"reference"},{"passageId":"u7_13_reference_passage_2","contextId":"u7_13_reference_gap_2","text":"Teachers are often asked to write a ____ when a student applies for a university place. A strong one gives specific examples of the student’s work instead of using only general praise.","answer":"reference"}],"contextDependentParaphrases":[],"wrongParaphrases":["mention of something in passing","list of books used in an essay","number used to identify an order"],"misleadingDistractors":["a short mention of something in a conversation","a list of books used to write an essay","a number used to identify an order"],"teacherNote":"Taught in its job and college sense only: a short written statement from someone who knows you, saying whether you are suitable. The other senses (a mention of something; a list of sources; a code number) are not taught here. Related target in this unit: referee (the person who writes it). Note the common phrasing: write / provide / ask for a reference."}]'::jsonb,'[]'::jsonb,'["write a reference","a good reference","a reference from a previous employer"]'::jsonb,'live'),
('vocab_proficiency','proficiency','noun','a high level of skill or ability, especially in a language or a practical task','[{"senseId":"proficiency_1","meaning":"a high level of skill or ability, especially in a language or a practical task","acceptedParaphrases":["high level of skill","ability to do something very well"],"masteryContexts":[{"contextId":"u7_14_proficiency_meaning","text":"Candidates must show proficiency in written English before they are offered a place on the course.","meaning":"a high level of skill or ability","wrongMeanings":["a low level of confidence or interest","a short break between two lessons","a feeling of pride in a piece of work"]},{"contextId":"u7_14_proficiency_paraphrase","text":"Her proficiency with spreadsheets saved the team hours of work every week.","meaning":"a high level of skill in doing something","wrongMeanings":["a delay in finishing something","a mistake made when doing something","a plan for doing something later"]}],"situationDistractors":["A girl spoke fluent Spanish at the interview and corrected the interviewer’s small mistake.","A boy completed a complicated spreadsheet in half the time allowed.","A woman passed the advanced language test with the highest mark in the room.","The cleaner locked the office and switched off all the lights.","Two students carried a heavy box of books up the stairs.","The receptionist watered the plants beside the main entrance."],"gapDistractors":[{"contextId":"u7_14_proficiency_gap_1","answer":"proficiency","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_14_proficiency_gap_2","answer":"proficiency","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_14_proficiency_gap_3","answer":"proficiency","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["proficency","proficiancy","profisiency","prooficiency","profficiency","proficiensy"],"masteryPassages":[{"passageId":"u7_14_proficiency_passage_1","contextId":"u7_14_proficiency_gap_1","text":"The advertisement said that no experience was necessary, but it asked for strong ____ in English because the job involved talking to customers all day. Applicants had to take a short speaking test.","answer":"proficiency"},{"passageId":"u7_14_proficiency_passage_2","contextId":"u7_14_proficiency_gap_2","text":"Learning the basics of a language is only the first stage. To reach ____, you must practise speaking and writing until you can use it easily and accurately in different situations.","answer":"proficiency"}],"contextDependentParaphrases":[],"wrongParaphrases":["very low level of ability","certificate that a course has begun","feeling of pride after finishing"],"misleadingDistractors":["a very low level of ability in something","a certificate that a course has started","a feeling of pride after finishing a task"],"teacherNote":"Noun: a high level of skill or ability, especially in a language, a test or a practical job (proficiency in English, language proficiency). Boundary: proficiency is more than basic knowledge; it describes someone who does the task well. Often followed by in."}]'::jsonb,'[]'::jsonb,'["proficiency in English","language proficiency","a high level of proficiency"]'::jsonb,'live'),
('vocab_enthusiastic','enthusiastic','adjective','showing great interest, energy and excitement about something','[{"senseId":"enthusiastic_1","meaning":"showing great interest, energy and excitement about something","acceptedParaphrases":["full of interest and energy","keen and excited"],"masteryContexts":[{"contextId":"u7_15_enthusiastic_meaning","text":"The shop manager wanted an enthusiastic assistant who enjoyed talking to customers.","meaning":"full of interest and energy","wrongMeanings":["quiet and unwilling to speak","tired and ready to leave","careful and slow to decide"]},{"contextId":"u7_15_enthusiastic_paraphrase","text":"Nobody could miss how enthusiastic the whole team was about the new project.","meaning":"very keen and excited","wrongMeanings":["very worried and unsure","very busy and tired","very angry and upset"]}],"situationDistractors":["A girl smiled, leaned forward and asked three questions about the new project.","A boy talked eagerly about the club and could not wait to start.","A woman told the panel that she had dreamed of this job since she was a child.","The bus stopped outside the school and the driver opened the doors.","A woman folded the map and put it in her bag.","The class waited in the corridor until the exam hall was ready."],"gapDistractors":[{"contextId":"u7_15_enthusiastic_gap_1","answer":"enthusiastic","wrong":["careless","frozen","rectangular"]},{"contextId":"u7_15_enthusiastic_gap_2","answer":"enthusiastic","wrong":["wooden","furious","enormous"]},{"contextId":"u7_15_enthusiastic_gap_3","answer":"enthusiastic","wrong":["crowded","distant","bitter"]}],"spellingErrors":["enthusiasic","enthusastic","enthusiatic","entusiastic","enthusiastik","enthuseastic"],"wordFamilyForms":[{"form":"enthusiastic","partOfSpeech":"adjective","example":"The audience gave an enthusiastic round of applause at the end of the talk.","pedagogicallyUseful":true},{"form":"enthusiasm","partOfSpeech":"noun","example":"Her enthusiasm for science made every lesson more interesting for her classmates.","pedagogicallyUseful":true,"altExample":"The interviewer liked the enthusiasm that the young candidate showed for the job."},{"form":"enthusiastically","partOfSpeech":"adverb","example":"He answered every question enthusiastically and never looked at the clock.","pedagogicallyUseful":true,"altExample":"The children clapped enthusiastically when the magician appeared on stage."}],"masteryPassages":[{"passageId":"u7_15_enthusiastic_passage_1","contextId":"u7_15_enthusiastic_gap_1","text":"Employers know that skills can be taught, but a positive attitude is harder to change. They often prefer a(n) ____ person who is eager to learn over an experienced person who seems bored.","answer":"enthusiastic"},{"passageId":"u7_15_enthusiastic_passage_2","contextId":"u7_15_enthusiastic_gap_2","text":"During the interview, Tomas leaned forward, spoke quickly and smiled whenever he mentioned the sports club. His ____ manner showed the panel that he genuinely wanted the job.","answer":"enthusiastic"}],"contextDependentParaphrases":[],"wrongParaphrases":["quiet and unwilling to speak","tired and ready to leave","afraid and unsure of the answer"],"misleadingDistractors":["showing no interest in something","afraid of making a mistake","angry about a decision"],"teacherNote":"Adjective: showing great interest, energy and excitement about something (enthusiastic about, an enthusiastic team). It is used with about or for. Boundary: enthusiastic shows positive energy; it is stronger than interested and can be seen in the voice and body language."}]'::jsonb,'["enthusiasm","enthusiastically"]'::jsonb,'["enthusiastic about","an enthusiastic response","an enthusiastic team"]'::jsonb,'live'),
('vocab_availability_7','availability','noun','the time when a person is free to attend a meeting or start work','[{"senseId":"availability_7_1","meaning":"the time when a person is free to attend a meeting or start work","acceptedParaphrases":["times when someone is free","whether a person can attend"],"masteryContexts":[{"contextId":"u7_16_availability_7_meaning","text":"The company asked each candidate to confirm their availability for a second interview on Thursday or Friday.","meaning":"the times when someone is free to attend","wrongMeanings":["the level of skill that someone has reached","the amount of pay that someone expects","the number of jobs that someone has done"]},{"contextId":"u7_16_availability_7_paraphrase","text":"Because of her limited availability on weekdays, Sofia could only accept evening shifts.","meaning":"the times when a person is free to work","wrongMeanings":["the number of days a person has worked","the reasons a person gives for leaving","the order in which a person completes tasks"]}],"situationDistractors":["A student told the manager that she could work on Saturdays and Sundays but not on weekdays.","A man replied that he could start the new job at the beginning of next month.","A woman sent the panel a list of all the days she could come in for a meeting.","The librarian put the returned books back on the shelves.","A taxi stopped outside the hotel and the driver opened the boot.","Two friends argued about which film to watch on Saturday night."],"gapDistractors":[{"contextId":"u7_16_availability_7_gap_1","answer":"availability","wrong":["recipe","harbour","ticket"]},{"contextId":"u7_16_availability_7_gap_2","answer":"availability","wrong":["neighbour","umbrella","museum"]},{"contextId":"u7_16_availability_7_gap_3","answer":"availability","wrong":["souvenir","carpet","staircase"]}],"spellingErrors":["availablity","avalibility","availabilty","aviability","availibility","availabilaty"],"wordFamilyForms":[{"form":"availability","partOfSpeech":"noun","example":"Please send your availability for the week after the holiday.","pedagogicallyUseful":true},{"form":"available","partOfSpeech":"adjective","example":"The manager will be available to meet candidates after two o’clock.","pedagogicallyUseful":true,"altExample":"Are you available for a short telephone call tomorrow morning?"},{"form":"unavailable","partOfSpeech":"adjective","example":"The head of department is unavailable on Monday because she is visiting another school.","pedagogicallyUseful":true,"altExample":"Candidates who are unavailable on the interview day should contact the office at once."}],"masteryPassages":[{"passageId":"u7_16_availability_7_passage_1","contextId":"u7_16_availability_7_gap_1","text":"The manager had six candidates to see and only two free days. She emailed each one and asked about their ____, then placed the interviews in the gaps in their timetables.","answer":"availability"},{"passageId":"u7_16_availability_7_passage_2","contextId":"u7_16_availability_7_gap_2","text":"The job was in a café that opened early and closed late, so the owner wanted staff who could work flexible hours. Before offering anyone a contract, he asked each person about their ____ at weekends.","answer":"availability"}],"contextDependentParaphrases":[],"wrongParaphrases":["number of years someone has worked","promise to arrive earlier","money someone expects to earn"],"misleadingDistractors":["the number of years someone has worked","a promise to arrive earlier than planned","the amount of money someone expects to earn"],"teacherNote":"Unit 7 item (availability_7), separate from the Unit 2 and Unit 5 availability items; it shares only the lexical spelling list. Sense in this unit: the time when a person is free to attend a meeting, start work or take part. Boundary: this is about a person’s free time, not whether a room, seat or product can be obtained."}]'::jsonb,'["available","unavailable"]'::jsonb,'["check your availability","limited availability","confirm your availability"]'::jsonb,'live'),
('vocab_compromise','compromise','noun','an agreement in which each side accepts less than it wanted in order to settle a disagreement','[{"senseId":"compromise_1","meaning":"an agreement in which each side accepts less than it wanted in order to settle a disagreement","acceptedParaphrases":["agreement where both sides give something up","middle solution that both sides accept"],"masteryContexts":[{"contextId":"u7_17_compromise_meaning","text":"The students could not agree on a date, so they reached a compromise and met on Saturday morning.","meaning":"an agreement where each side gives something up","wrongMeanings":["an order that must be obeyed by everyone","a reason for ending a friendship","a plan that nobody has agreed to"]},{"contextId":"u7_17_compromise_paraphrase","text":"In the group task, Leila suggested a compromise by using ideas from both teams.","meaning":"a solution that both sides accept","wrongMeanings":["a decision made by the loudest speaker","a rule that stops people from speaking","a mistake made by a whole team"]}],"situationDistractors":["Two friends could not agree on a restaurant, so each chose one dish for the table and they ate at a place in the middle.","A manager and a worker agreed on shorter hours and a smaller salary after a long talk.","Two sides in a debate each accepted a change to their proposal so that a plan could go ahead.","The coach shouted at the players as the rain became heavier.","A lorry delivered boxes of fruit to the market early in the morning.","The student tidied her desk and closed all the windows."],"gapDistractors":[{"contextId":"u7_17_compromise_gap_1","answer":"compromise","wrong":["holiday","recipe","invitation"]},{"contextId":"u7_17_compromise_gap_2","answer":"compromise","wrong":["souvenir","umbrella","sandwich"]},{"contextId":"u7_17_compromise_gap_3","answer":"compromise","wrong":["carpet","staircase","bicycle"]}],"spellingErrors":["comprimise","compromize","compermise","compromis","compramise","compromice"],"masteryPassages":[{"passageId":"u7_17_compromise_passage_1","contextId":"u7_17_compromise_gap_1","text":"The two managers wanted different people for the job, and neither would change their mind. At last, they agreed that the winner would be chosen after a second interview, which was a ____ that both could accept.","answer":"compromise"},{"passageId":"u7_17_compromise_passage_2","contextId":"u7_17_compromise_gap_2","text":"In a group discussion, you do not need to win every point. Sometimes the best answer is to suggest a ____ that takes a little from each person’s idea.","answer":"compromise"}],"contextDependentParaphrases":[],"wrongParaphrases":["decision made by one person alone","promise to do what the other wants","argument that goes on for a long time"],"misleadingDistractors":["a decision made by one person without asking anyone","a promise to do exactly what the other side wants","an argument that continues for a long time"],"teacherNote":"Noun: an agreement in which each side accepts less than it wanted (reach a compromise, make a compromise). In discussions and interviews it shows the ability to work with others. The verb (to compromise on something) is a separate use of the same word and is not taught as its own item. The sense of putting something at risk is not taught."}]'::jsonb,'[]'::jsonb,'["reach a compromise","a reasonable compromise","find a compromise"]'::jsonb,'live'),
('vocab_dominate','dominate','verb','to have the most control or influence in a situation, or to speak so much that others cannot','[{"senseId":"dominate_1","meaning":"to have the most control or influence in a situation, or to speak so much that others cannot","acceptedParaphrases":["have the most control over","take over by being the loudest"],"masteryContexts":[{"contextId":"u7_18_dominate_meaning","text":"One student tried to dominate the discussion, so the others had hardly any chance to speak.","meaning":"to take control by speaking too much","wrongMeanings":["to guide the discussion in a fair way","to leave the discussion before it ends","to record the discussion for later use"]},{"contextId":"u7_18_dominate_paraphrase","text":"A few large companies dominate the market for mobile phones in this region.","meaning":"to have the most control or influence over","wrongMeanings":["to buy the smallest share of","to refuse to work with","to copy the products of"]}],"situationDistractors":["One boy talked for most of the meeting and interrupted every person who tried to speak.","Two large supermarkets control almost all of the food sales in the town.","A tall player controlled the ball at every moment of the match and her team scored most of the goals.","A woman handed over her passport at the airport desk.","The class sat in a circle and passed a ball from hand to hand.","The cook checked the oven and then washed the dishes."],"gapDistractors":[{"contextId":"u7_18_dominate_gap_1","answer":"dominate","wrong":["borrow","repair","forget"]},{"contextId":"u7_18_dominate_gap_2","answer":"dominate","wrong":["invent","decorate","translate"]},{"contextId":"u7_18_dominate_gap_3","answer":"dominate","wrong":["postpone","photograph","celebrate"]}],"spellingErrors":["dominat","dominete","domminate","domanate","domenate","domminat"],"wordFamilyForms":[{"form":"dominate","partOfSpeech":"verb","example":"A few large firms dominate the online shopping market.","pedagogicallyUseful":true},{"form":"dominant","partOfSpeech":"adjective","example":"The dominant member of the group did most of the talking in the task.","pedagogicallyUseful":true,"altExample":"English is the dominant language of international business."},{"form":"dominance","partOfSpeech":"noun","example":"The company’s dominance of the market made it difficult for new businesses to start.","pedagogicallyUseful":true,"altExample":"The team’s dominance in the first half made the result look certain."}],"masteryPassages":[{"passageId":"u7_18_dominate_passage_1","contextId":"u7_18_dominate_gap_1","text":"In the group task, the assessors were not looking for the loudest person. They watched to see who could listen, who could include quiet students and who tried to ____ every discussion.","answer":"dominate"},{"passageId":"u7_18_dominate_passage_2","contextId":"u7_18_dominate_gap_2","text":"Only three companies sell most of the world’s trainers, and they ____ the market so strongly that small brands find it hard to compete. A new company needs a very different idea if it hopes to win customers.","answer":"dominate"}],"contextDependentParaphrases":[],"wrongParaphrases":["to listen carefully to","to give way to","to share equally with"],"misleadingDistractors":["to listen carefully to the other speakers","to give way to someone more experienced","to share the work equally with everyone"],"teacherNote":"Verb: to have the most control or influence over a situation, or to speak or act so much that others have no chance (dominate a discussion, dominate the market). In interviews it describes a negative behaviour in group tasks. Boundary: dominate suggests too much control; lead suggests guiding others in a positive way. Other forms (dominant, dominance) are taught in the Word Family pathway."}]'::jsonb,'["dominant","dominance"]'::jsonb,'["dominate a discussion","dominate the market","tend to dominate"]'::jsonb,'live'),
('vocab_strategy_7','strategy','noun','a plan for dealing with a difficult situation or achieving a goal such as doing well in an interview','[{"senseId":"strategy_7_1","meaning":"a plan for dealing with a difficult situation or achieving a goal such as doing well in an interview","acceptedParaphrases":["plan for achieving a goal","planned way of dealing with a difficulty"],"masteryContexts":[{"contextId":"u7_19_strategy_7_meaning","text":"Her strategy for difficult questions was to pause, take a breath and then answer slowly.","meaning":"a plan for dealing with a difficult situation","wrongMeanings":["a mistake that happens in difficult situations","a reason for avoiding difficult situations","a question asked about a difficult situation"]},{"contextId":"u7_19_strategy_7_paraphrase","text":"The company changed its strategy and began to recruit more people from local schools.","meaning":"a plan for achieving an important aim","wrongMeanings":["a promise to change an old rule","a list of the people already employed","a report about last year’s sales"]}],"situationDistractors":["A girl decided to prepare three short stories about her school life before the interview so that she could use them in any answer.","A manager made a plan to open two new shops in the north of the country over three years.","A football coach planned how the team would defend in the first half and attack in the second.","The bus was late because of the heavy traffic on the main road.","A student carried a large poster into the hall and fixed it to the wall.","The teacher handed back the marked essays at the end of the lesson."],"gapDistractors":[{"contextId":"u7_19_strategy_7_gap_1","answer":"strategy","wrong":["recipe","invitation","souvenir"]},{"contextId":"u7_19_strategy_7_gap_2","answer":"strategy","wrong":["umbrella","sandwich","carpet"]},{"contextId":"u7_19_strategy_7_gap_3","answer":"strategy","wrong":["staircase","bicycle","neighbour"]}],"spellingErrors":["stratagy","stratergy","strategi","stradegy","startegy","stategy"],"wordFamilyForms":[{"form":"strategy","partOfSpeech":"noun","example":"A clear strategy can help you to stay calm during an interview.","pedagogicallyUseful":true},{"form":"strategic","partOfSpeech":"adjective","example":"The manager made a strategic decision to open an office in a larger city.","pedagogicallyUseful":true,"altExample":"A strategic plan for the next five years was presented to the whole staff."},{"form":"strategically","partOfSpeech":"adverb","example":"The team positioned the tables strategically so that every customer could see the stage.","pedagogicallyUseful":true,"altExample":"The shop is strategically placed near the station, which brings in many customers."}],"masteryPassages":[{"passageId":"u7_19_strategy_7_passage_1","contextId":"u7_19_strategy_7_gap_1","text":"Ravi was nervous about unexpected questions, so he developed a simple ____. He would pause for two seconds, repeat the question in his head and only then begin to speak.","answer":"strategy"},{"passageId":"u7_19_strategy_7_passage_2","contextId":"u7_19_strategy_7_gap_2","text":"The restaurant was losing customers, so the new owner changed the ____ completely. She lowered the prices, simplified the menu and advertised in the local school.","answer":"strategy"}],"contextDependentParaphrases":[],"wrongParaphrases":["short break during a meeting","rule that nobody can change","mistake that happens often"],"misleadingDistractors":["a short break taken during a long meeting","a rule that nobody is allowed to change","a mistake that is repeated several times"],"teacherNote":"Unit 7 item (strategy_7), separate from the Unit 6 strategy item; it shares only the lexical spelling list with the Unit 6 item. Sense in this unit: a plan for dealing with a difficult situation or achieving a goal, here the plan for answering questions in an interview or test. Boundary: a strategy is the overall plan; a technique is one particular skilled method (technique is also a target in this unit)."}]'::jsonb,'["strategic","strategically"]'::jsonb,'["develop a strategy","an effective strategy","a long-term strategy"]'::jsonb,'live'),
('vocab_flexible','flexible','adjective','able to change or adapt easily to new situations, times or plans','[{"senseId":"flexible_1","meaning":"able to change or adapt easily to new situations, times or plans","acceptedParaphrases":["able to change easily","willing to adapt to new plans"],"masteryContexts":[{"contextId":"u7_20_flexible_meaning","text":"The café offers flexible hours, so students can work around their lessons.","meaning":"able to be changed to suit different needs","wrongMeanings":["fixed so that nobody can change them","long enough to fill the whole day","shorter than at most other places"]},{"contextId":"u7_20_flexible_paraphrase","text":"She was flexible when the plan changed and quickly found another room for the meeting.","meaning":"willing and able to adapt to a change","wrongMeanings":["unwilling to accept any new idea","unable to understand the new plan","angry about the cost of the change"]}],"situationDistractors":["A student agreed to swap shifts with a colleague at the last minute and did not complain.","A manager allowed workers to start and finish at different times to suit family life.","A girl changed her plan quickly when the bus was cancelled and walked to the interview instead.","A boy tied his shoelaces and then ran to catch the school bus.","The librarian stamped each book and put it on the trolley.","Heavy rain fell on the roof of the bus shelter all afternoon."],"gapDistractors":[{"contextId":"u7_20_flexible_gap_1","answer":"flexible","wrong":["frozen","rectangular","wooden"]},{"contextId":"u7_20_flexible_gap_2","answer":"flexible","wrong":["enormous","furious","distant"]},{"contextId":"u7_20_flexible_gap_3","answer":"flexible","wrong":["bitter","crowded","careless"]}],"spellingErrors":["flexable","flexibel","flexibal","flexble","flexsible","flecible"],"wordFamilyForms":[{"form":"flexible","partOfSpeech":"adjective","example":"Employers value people who are flexible and ready to learn new skills.","pedagogicallyUseful":true},{"form":"flexibility","partOfSpeech":"noun","example":"The job offers flexibility, so employees can choose when they start and finish.","pedagogicallyUseful":true,"altExample":"Good communication and flexibility are the most important qualities for the role."},{"form":"flexibly","partOfSpeech":"adverb","example":"The team worked flexibly, so some members stayed late and others came in early.","pedagogicallyUseful":true,"altExample":"Students who study flexibly can fit their lessons around part-time work."}],"masteryPassages":[{"passageId":"u7_20_flexible_passage_1","contextId":"u7_20_flexible_gap_1","text":"The manager explained that the work was unpredictable, and that she needed people who would not complain when the plan changed. She was looking for someone ____ enough to start early one day and finish late the next.","answer":"flexible"},{"passageId":"u7_20_flexible_passage_2","contextId":"u7_20_flexible_gap_2","text":"Many students look for a part-time job with ____ hours. This allows them to move their shifts around when exams or school trips make them busy.","answer":"flexible"}],"contextDependentParaphrases":[],"wrongParaphrases":["unwilling to change any plan","able to do only one job","quick to feel upset"],"misleadingDistractors":["unwilling to change any plans","able to do only one task well","quick to become angry or upset"],"teacherNote":"Adjective: able to change or adapt easily to new situations, times or plans (flexible hours, a flexible approach). In interviews it describes a positive quality in a worker. Boundary: flexible about plans is positive; it is not the same as weak, because a flexible person still has opinions. The physical sense (a flexible material) is not taught here."}]'::jsonb,'["flexibility","flexibly"]'::jsonb,'["flexible hours","a flexible approach","flexible about"]'::jsonb,'live')
