('u7_13_reference_gap_3','vocab_reference','u7_13_reference','reference_1','gap_fill','He asked his tutor to write a reference that mentioned his leadership of the school newspaper.','reference','["reference"]'::jsonb,null,'live'),
('u7_14_proficiency_meaning','vocab_proficiency','u7_14_proficiency','proficiency_1','meaning_context','The job advertisement asked for proof of proficiency in English and one other language.',null,'["high level of skill"]'::jsonb,null,'live'),
('u7_14_proficiency_paraphrase','vocab_proficiency','u7_14_proficiency','proficiency_1','paraphrase_context','The job advertisement asked for proof of a high level of skill in English and one other language.','a high level of skill','["proficiency"]'::jsonb,null,'live'),
('u7_14_proficiency_production','vocab_proficiency','u7_14_proficiency','proficiency_1','production_context','A university will usually test your ability to do something very well before it gives you a place on the course.','ability to do something very well','["proficiency"]'::jsonb,null,'live'),
('u7_14_proficiency_gap_1','vocab_proficiency','u7_14_proficiency','proficiency_1','gap_fill','The company expects a high level of proficiency in English from everyone in the customer team.','proficiency','["proficiency"]'::jsonb,null,'live'),
('u7_14_proficiency_gap_2','vocab_proficiency','u7_14_proficiency','proficiency_1','gap_fill','Her proficiency in three languages made her the strongest applicant.','proficiency','["proficiency"]'::jsonb,null,'live'),
('u7_14_proficiency_gap_3','vocab_proficiency','u7_14_proficiency','proficiency_1','gap_fill','Employers often test computer proficiency before they invite people to a final interview.','proficiency','["proficiency"]'::jsonb,null,'live'),
('u7_15_enthusiastic_meaning','vocab_enthusiastic','u7_15_enthusiastic','enthusiastic_1','meaning_context','The interviewer was pleased to meet such an enthusiastic young applicant.',null,'["full of interest and energy"]'::jsonb,null,'live'),
('u7_15_enthusiastic_paraphrase','vocab_enthusiastic','u7_15_enthusiastic','enthusiastic_1','paraphrase_context','The interviewer was pleased to meet such a keen and excited young applicant.','keen and excited','["enthusiastic"]'::jsonb,null,'live'),
('u7_15_enthusiastic_production','vocab_enthusiastic','u7_15_enthusiastic','enthusiastic_1','production_context','Employers often choose people who seem full of interest and energy, even if they have less experience.','full of interest and energy','["enthusiastic"]'::jsonb,null,'live'),
('u7_15_enthusiastic_gap_1','vocab_enthusiastic','u7_15_enthusiastic','enthusiastic_1','gap_fill','She was not the most experienced applicant, but she was the most enthusiastic about learning new skills.','enthusiastic','["enthusiastic"]'::jsonb,null,'live'),
('u7_15_enthusiastic_gap_2','vocab_enthusiastic','u7_15_enthusiastic','enthusiastic_1','gap_fill','An enthusiastic speaker can make even a dull subject interesting for the audience.','enthusiastic','["enthusiastic"]'::jsonb,null,'live'),
('u7_15_enthusiastic_gap_3','vocab_enthusiastic','u7_15_enthusiastic','enthusiastic_1','gap_fill','The manager was impressed by his enthusiastic answers and his willingness to start immediately.','enthusiastic','["enthusiastic"]'::jsonb,null,'live'),
('u7_16_availability_7_meaning','vocab_availability_7','u7_16_availability_7','availability_7_1','meaning_context','Please email your availability for next week so that we can arrange the interviews.',null,'["times when someone is free"]'::jsonb,null,'live'),
