('u7_20_flexible_gap_2','vocab_flexible','u7_20_flexible','flexible_1','gap_fill','Because the project changed three times, the team had to be flexible and adjust their plans.','flexible','["flexible"]'::jsonb,null,'live'),
('u7_20_flexible_gap_3','vocab_flexible','u7_20_flexible','flexible_1','gap_fill','A flexible timetable allows parents to start work later and finish earlier.','flexible','["flexible"]'::jsonb,null,'live')
